// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics.FilterPassEstimate;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PatternKey;
import org.junit.jupiter.api.Test;

/**
 * Unit spec for the sketch-free learned filter selectivity store.
 * <p>
 * The behaviour that matters is the three-tier waterfall — the most specific evidence available wins — and the refusal
 * to answer at all when there is nothing worth reporting, because a null answer leaves the caller on its conservative
 * "passes everything, confidence zero" default rather than on a fabricated ratio.
 */
public class LmdbLearnedFilterSelectivityTest {

	private static final PatternKey PATTERN = new PatternKey(
			SimpleValueFactory.getInstance().createIRI("http://example.com/p"), PatternKey.PREDICATE_BOUND);
	private static final PatternKey OTHER_PATTERN = new PatternKey(
			SimpleValueFactory.getInstance().createIRI("http://example.com/q"), PatternKey.PREDICATE_BOUND);

	private static final String FILTER = "filter-key";
	private static final String TEMPLATE = "template-key";

	@Test
	public void learnsTheObservedPassRatio() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();
		stats.recordFilterOutcome(PATTERN, FILTER, TEMPLATE, 20L, 80L, true);

		FilterPassEstimate estimate = stats.estimate(PATTERN, FILTER, TEMPLATE);

		assertThat(estimate).isNotNull();
		assertThat(estimate.getPassRatio()).isCloseTo(0.2d, within(1e-9));
		assertThat(estimate.getSource()).isEqualTo(FilterPassEstimate.Source.LEARNED_FILTER);
	}

	@Test
	public void repeatedObservationsAccumulate() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();
		for (int i = 0; i < 10; i++) {
			stats.recordFilterOutcome(PATTERN, FILTER, TEMPLATE, 1L, 9L, true);
		}

		FilterPassEstimate estimate = stats.estimate(PATTERN, FILTER, TEMPLATE);

		assertThat(estimate.getPassRatio()).isCloseTo(0.1d, within(1e-9));
		assertThat(estimate.getEvidenceCount())
				.as("evidence is what the Wilson interval is derived from, so it must reflect every observed row")
				.isEqualTo(100L);
	}

	@Test
	public void fallsBackToTheTemplateWhenTheExactFilterIsUnseen() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();
		stats.recordFilterOutcome(PATTERN, "some-other-filter", TEMPLATE, 5L, 95L, true);

		FilterPassEstimate estimate = stats.estimate(PATTERN, FILTER, TEMPLATE);

		assertThat(estimate.getSource())
				.as("a constant-abstracted template lets ?x > 5 inform ?x > 7")
				.isEqualTo(FilterPassEstimate.Source.LEARNED_TEMPLATE);
		assertThat(estimate.getPassRatio()).isCloseTo(0.05d, within(1e-9));
	}

	@Test
	public void fallsBackToThePatternWhenNeitherFilterNorTemplateIsSeen() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();
		stats.recordFilterOutcome(PATTERN, "other-filter", "other-template", 50L, 50L, true);

		FilterPassEstimate estimate = stats.estimate(PATTERN, FILTER, TEMPLATE);

		assertThat(estimate.getSource()).isEqualTo(FilterPassEstimate.Source.LEARNED_PATTERN);
		assertThat(estimate.getPassRatio()).isCloseTo(0.5d, within(1e-9));
	}

	@Test
	public void qualifiedObservationsDoNotPolluteThePatternTier() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();
		// unqualified=false: this filter's key is qualified by locally bound components, so folding it into the
		// pattern-wide tier would average over genuinely different bound shapes.
		stats.recordFilterOutcome(PATTERN, "other-filter", "other-template", 50L, 50L, false);

		assertThat(stats.estimate(PATTERN, FILTER, TEMPLATE))
				.as("nothing generalizable was observed for this pattern")
				.isNull();
	}

	@Test
	public void thinEvidenceIsNotReportedAsLearned() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();
		stats.recordFilterOutcome(PATTERN, FILTER, TEMPLATE, 1L, 2L, true);

		assertThat(stats.estimate(PATTERN, FILTER, TEMPLATE))
				.as("three rows is not a selectivity measurement; the caller must keep its conservative default")
				.isNull();
	}

	@Test
	public void unseenFilterYieldsNoEstimate() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();

		assertThat(stats.estimate(OTHER_PATTERN, "unseen", "unseen-template")).isNull();
	}

	@Test
	public void emptyObservationsAreIgnored() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();
		stats.recordFilterOutcome(PATTERN, FILTER, TEMPLATE, 0L, 0L, true);
		stats.recordFilterOutcome(PATTERN, FILTER, TEMPLATE, -1L, 5L, true);

		assertThat(stats.size()).isZero();
		assertThat(stats.estimate(PATTERN, FILTER, TEMPLATE)).isNull();
	}

	@Test
	public void storeIsBoundedSoUnboundedFilterVarietyCannotGrowIt() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();
		for (int i = 0; i < 20_000; i++) {
			stats.recordFilterOutcome(PATTERN, "filter-" + i, "template-" + i, 10L, 10L, true);
		}

		assertThat(stats.size())
				.as("three tiers, each capped; a workload with unbounded filter variety stops learning new keys "
						+ "rather than growing without limit")
				.isLessThanOrEqualTo(3 * 4096 + 1);
	}

	@Test
	public void aFilterThatRejectsEverythingIsLearnedAsSuch() {
		LmdbLearnedFilterSelectivity stats = new LmdbLearnedFilterSelectivity();
		stats.recordFilterOutcome(PATTERN, FILTER, TEMPLATE, 0L, 1000L, true);

		FilterPassEstimate estimate = stats.estimate(PATTERN, FILTER, TEMPLATE);

		assertThat(estimate).isNotNull();
		assertThat(estimate.getPassRatio()).isZero();
	}
}
